/**
 * Collision-safe Markdown heading-anchor contract (paired acceptance tests;
 * the paired build must keep this file unchanged and make it pass).
 *
 * Outcome: in a standalone rendered Markdown document, a fragment link
 * resolves to exactly one heading, and every heading id that is unique today
 * stays byte-identical so existing deep links keep working.
 *
 * The defect today: only Markdown-rendered headings are registered in the
 * duplicate-id ("seen") map, so a raw-HTML heading with an authored id
 * followed by a Markdown heading that slugs to the same id produces two
 * headings with the same id, and the second one is unreachable by fragment.
 *
 * The bounded fix this pins (first heading in document order wins):
 *
 * - (a) The first heading in document order keeps its id. Every heading whose
 *   id is unique today keeps it byte-identical. ONLY a Markdown-generated
 *   heading that currently duplicates an earlier raw-HTML heading id takes
 *   an unused `-1`-style suffix, reserving existing heading destinations first:
 *   that later occurrence is unreachable by fragment today, so nothing that
 *   resolves today moves. Any renumbering beyond this one exception fails.
 * - (b) Raw-HTML heading ids are author-supplied and never rewritten.
 *   Raw-before-Markdown: the later Markdown heading takes the suffix.
 *   Markdown-before-raw: the Markdown id stays and the raw id is left as
 *   authored. Raw-vs-raw duplicates stay exactly as authored (out of scope);
 *   non-heading element ids are out of scope.
 * - (c) Sanitizer id-attribute handling is unchanged: a raw heading with an
 *   authored id is served with that id; a raw heading without an id is
 *   served without one.
 * - (d) Documents without the raw/Markdown collision render byte-identical
 *   output, so the Markdown render version (3 until now) must rise to retire
 *   cached `markdown@3` fragments and render ETags only together with the
 *   collision-case change above. Both are pinned here: the bytes tests fail
 *   on any wider output change; the version tests fail if the collision fix
 *   ships without the bump (a stale cached fragment or ETag would keep
 *   serving the ambiguous ids).
 *
 * Every case runs the served Worker (`freshInstance` + real publish/serve)
 * or the exported `renderMarkdown`/`markdownViewer` the viewer itself calls.
 * Nothing is reimplemented: ids are decoded entities read from the served
 * HTML with HTMLRewriter, byte identity compares the full served body
 * against golden bytes captured from render version 3, and the ETag checks
 * go through real conditional requests. The renumber guard needs a
 * pre-change baseline, so the per-document heading-id sequences captured
 * from render version 3 are embedded below as labelled golden data
 * (BASELINE_IDS) and compared by exact order for every heading that is not
 * the one named suffix exception.
 */
import { createExecutionContext, env, waitOnExecutionContext } from "cloudflare:test";
import { beforeAll, beforeEach, describe, expect, it } from "vitest";
import { sha256Hex } from "@dropway/core";
import type { ServerBindings } from "@dropway/server";
import { cachedRender, clearRenderMemoryCache } from "../packages/server/src/viewers/cache";
import { markdownViewer, renderMarkdown } from "../packages/server/src/viewers/markdown";
import { form, freshInstance, ORIGIN, type Instance } from "./helpers";

const NAV = { Accept: "text/html,application/xhtml+xml,*/*;q=0.8", "Sec-Fetch-Dest": "document", "Sec-Fetch-Mode": "navigate" };

/** Render version whose behaviour the goldens below were captured from. */
const BASELINE_MD_VERSION = 3;

const fixtures: Record<string, string> = {
  /** The reproduced defect: raw-HTML h2 first, Markdown heading with the same slug after. */
  "repro.md": '# Report Title\n\n<h2 id="markdown-section">Raw Section</h2>\n\n## Markdown Section\n\nBody text.\n',
  /** Raw h3 before a Markdown h2: levels need not match for ids to collide. */
  "raw-first-levels.md": '# Report Title\n\n<h3 id="details">Raw Details</h3>\n\n## Details\n\nBody.\n',
  /** Only the shadowed first Markdown heading moves; the later #notes-1 stays reachable. */
  "raw-first-triple.md": '# Report Title\n\n<h2 id="notes">Raw Notes</h2>\n\n## Notes\n\n## Notes\n',
  /** Markdown first, raw after: both keep their ids exactly as today. */
  "md-first.md": '# Report Title\n\n## Markdown Section\n\n<h2 id="markdown-section">Later Raw</h2>\n',
  /** Two raw headings sharing an id, no Markdown collision: pinned as-is. */
  "raw-vs-raw.md": '# Report Title\n\n<h2 id="shared">First Raw</h2>\n\n<h2 id="shared">Second Raw</h2>\n\n## Unique Section\n',
  /** Raw heading without an id: nothing is registered for it. */
  "raw-no-id.md": '# Report Title\n\n<h2>Unlabelled Raw</h2>\n\n## Unlabelled Raw\n',
  /**
   * Only ids that survive the sanitizer exist in the served document: the
   * script block is dropped with its id="kept", and the script inside a
   * paragraph is dropped while its text is not a heading; neither may
   * reserve an id for the later Markdown headings.
   */
  "dropped-ids.md": '# Report Title\n\n<script id="kept">alert(1)</script>\n\n## Kept\n\n<p><script id="inline">alert(2)</script></p>\n\n## Inline\n',
  /** Non-heading element ids are out of scope and register nothing. */
  "non-heading-id.md": '# Report Title\n\n<div id="section-notes">Panel</div>\n\n## Section Notes\n',
  /** Raw heading whose id collides with nothing: bytes and ids unchanged. */
  "raw-unique.md": '# Markdown Title\n\n<h2 id="raw-custom">Raw HTML heading</h2>\n\n## Markdown Section\n',
  /** Raw-vs-raw duplicates plus a third Markdown heading: only the Markdown one may move (to -1). */
  "raw-pair-md.md": '# Report Title\n\n<h2 id="notes">Raw One</h2>\n\n<h2 id="notes">Raw Two</h2>\n\n## Notes\n',
  /** A collision must renumber only the colliding heading; neighbours keep their ids. */
  "collision-with-dupes.md":
    '# Report Title\n\n## Setup\n\n<h2 id="summary">Authored Summary</h2>\n\n## Summary\n\n## Setup\n\n## Wrap Up\n',
  /**
   * The raw id already carries the suffix the second Markdown heading would
   * take today (`## Notes` twice gives notes, notes-1). Registering the raw
   * id must not leave the second Markdown heading duplicating it: the
   * suffix advances past the reserved id. `notes-2` is unreachable today
   * (today's second heading duplicates the raw id), so this renumbers
   * nothing that resolves.
   */
  "suffixed-raw.md": '# Report Title\n\n<h2 id="notes-1">Authored Notes</h2>\n\n## Notes\n\n## Notes\n',
  /** No collision at all: served bytes must equal render version 3 bytes. */
  "plain.md": "# First Report\n\nIntro paragraph.\n\n## Second Section\n\nBody text.\n",
  /** Markdown-only duplicate slugs keep today's numbering exactly. */
  "dupes.md":
    "# Guide\n\n## Hello, World!\n\n## Hello, World!\n\n## Café — déjà vu\n\n## Café — déjà vu\n\n## !!!\n\n## !!!\n\n## 日本語 テスト\n\n## 日本語 テスト\n",
  /** Inline markup / hostile headings keep today's ids. */
  "inline.md":
    '# Safe <script>alert(1)</script> Title\n\n## Using `code` and **bold** text\n\n## Click <a href="javascript:alert(2)">here</a> now\n',
  /** Front matter + ATX/setext mix: no collision, byte-identical. */
  "frontmatter.md":
    "---\ntitle: Quarterly Report\n# not a heading, just front matter\n---\n# Real One\n\nSetext Title\n============\n\n## Real Two\n",
};

/**
 * Heading (depth;id) sequences of these fixtures under render version 3,
 * in document order. This is the "unique today" baseline for the renumber
 * guard: every entry must survive the fix byte-identical. (Headings served
 * without an id are omitted; the sanitizer test pins that separately.)
 */
const BASELINE_IDS: Record<string, string[]> = {
  "md-first.md": ["h1:report-title", "h2:markdown-section", "h2:markdown-section"],
  "raw-vs-raw.md": ["h1:report-title", "h2:shared", "h2:shared", "h2:unique-section"],
  "raw-no-id.md": ["h1:report-title", "h2:unlabelled-raw"],
  "dropped-ids.md": ["h1:report-title", "h2:kept", "h2:inline"],
  "non-heading-id.md": ["h1:report-title", "h2:section-notes"],
  "raw-unique.md": ["h1:markdown-title", "h2:raw-custom", "h2:markdown-section"],
  "plain.md": ["h1:first-report", "h2:second-section"],
  "dupes.md": [
    "h1:guide",
    "h2:hello-world",
    "h2:hello-world-1",
    "h2:café-déjà-vu",
    "h2:café-déjà-vu-1",
    "h2:section",
    "h2:section-1",
    "h2:日本語-テスト",
    "h2:日本語-テスト-1",
  ],
  "inline.md": ["h1:safe-alert1-title", "h2:using-code-and-bold-text", "h2:click-here-now"],
  "frontmatter.md": ["h1:real-one", "h1:setext-title", "h2:real-two"],
};

/**
 * Complete served bytes (UTF-8 base64), refreshed from main 923ac4b's Phone
 * chrome and independently matched against integrated feature a8b6cdd.
 * Removing only the Phone chrome recovers every original version-3 byte;
 * the article bytes remain unchanged. Keep full-page equality, not a slice.
 */
const GOLDEN_B64: Record<string, string> = {
  "plain.md":
    "",
  "raw-unique.md":
    "",
  "raw-vs-raw.md":
    "",
  "md-first.md":
    "",
  "dupes.md":
    "",
  "non-heading-id.md":
    "",
};

function decodeB64(b64: string): Uint8Array {
  return Uint8Array.from(atob(b64), (c) => c.charCodeAt(0));
}

interface Heading {
  depth: number;
  /** Decoded id, or null when the served heading carries no id attribute. */
  id: string | null;
  /** Whether this heading carries the renderer's own permalink anchor. */
  generated: boolean;
}

/** The viewer chrome and its file/folder navigation use headings too; the rendered prose lives in <article class="dw-md">. */
function articleHtml(pageHtml: string): string {
  const start = pageHtml.indexOf('<article class="dw-md">');
  expect(start, "served markdown page has a dw-md article").toBeGreaterThanOrEqual(0);
  const rest = pageHtml.slice(start);
  const end = rest.indexOf("</article>");
  expect(end, "dw-md article closes").toBeGreaterThanOrEqual(0);
  return rest.slice(0, end);
}

async function headingsIn(fragment: string): Promise<Heading[]> {
  const headings: Heading[] = [];
  await new HTMLRewriter()
    .on("h1,h2,h3,h4,h5,h6", {
      element(el) {
        headings.push({ depth: Number(el.tagName.slice(1)), id: el.getAttribute("id"), generated: false });
      },
    })
    .on("h1 a.dw-anchor,h2 a.dw-anchor,h3 a.dw-anchor,h4 a.dw-anchor,h5 a.dw-anchor,h6 a.dw-anchor", {
      element() {
        headings[headings.length - 1]!.generated = true;
      },
    })
    .transform(new Response(fragment, { headers: { "Content-Type": "text/html; charset=utf-8" } }))
    .text();
  return headings;
}

async function fragmentsIn(fragment: string): Promise<{ links: string[]; ids: string[] }> {
  const links: string[] = [];
  const ids: string[] = [];
  await new HTMLRewriter()
    .on("a[href]", {
      element(el) {
        const href = el.getAttribute("href")!;
        if (href.startsWith("#")) links.push(href.slice(1));
      },
    })
    .on("[id]", {
      element(el) {
        ids.push(el.getAttribute("id")!);
      },
    })
    .transform(new Response(fragment, { headers: { "Content-Type": "text/html; charset=utf-8" } }))
    .text();
  return { links, ids };
}

const idList = (headings: Heading[]): string[] => headings.map((h) => `h${h.depth}:${h.id}`).filter((s) => !s.endsWith(":null"));

function duplicates(values: string[]): string[] {
  const seen = new Set<string>();
  const dup = new Set<string>();
  for (const v of values) {
    if (seen.has(v)) dup.add(v);
    seen.add(v);
  }
  return [...dup];
}

describe("collision-safe Markdown heading anchors in workerd", () => {
  let dw: Instance;
  let slug: string;
  beforeAll(async () => {
    dw = await freshInstance();
    // Phone's QR encodes the URL in SVG geometry; text replacement cannot
    // normalize a random slug there. A fixed fixture URL keeps all bytes pinned.
    const published = await dw.json("/api/v1/publish", { method: "POST", key: dw.ownerKey, body: form(fixtures, { slug: "kofra-golden-slug" }) });
    expect(published.status).toBe(201);
    slug = published.body.slug;
  });
  beforeEach(() => clearRenderMemoryCache());
  const get = (path: string, headers: Record<string, string> = NAV) => dw.call(`/s/${slug}/${path}`, { headers });
  const page = async (path: string): Promise<string> => {
    const res = await get(path);
    expect(res.status).toBe(200);
    expect(res.headers.get("x-kofra-viewer")).toBe("markdown");
    return res.text();
  };
  const headingsOf = async (path: string): Promise<Heading[]> => headingsIn(articleHtml(await page(path)));

  it("suffixes only the later Markdown heading when a raw heading holds its id (raw-before-Markdown)", async () => {
    const headings = await headingsOf("repro.md");
    expect(idList(headings)).toEqual(["h1:report-title", "h2:markdown-section", "h2:markdown-section-1"]);
    const [title, raw, md] = headings;
    expect(title!.generated).toBe(true);
    expect(raw!.generated, "raw heading has no generated permalink").toBe(false);
    expect(md!.generated).toBe(true);
    expect(duplicates(idList(headings).map((s) => s.slice(3)))).toEqual([]);
  });

  it("collides by id across heading levels (raw h3 before Markdown h2)", async () => {
    const headings = await headingsOf("raw-first-levels.md");
    expect(idList(headings)).toEqual(["h1:report-title", "h3:details", "h2:details-1"]);
  });

  it("moves only the raw-shadowed Markdown heading and preserves the later #notes-1 destination", async () => {
    const headings = await headingsOf("raw-first-triple.md");
    expect(idList(headings)).toEqual(["h1:report-title", "h2:notes", "h2:notes-2", "h2:notes-1"]);
  });

  it("keeps the Markdown id when the raw heading comes later, raw id left as authored", async () => {
    const headings = await headingsOf("md-first.md");
    expect(idList(headings)).toEqual(BASELINE_IDS["md-first.md"]);
    expect(headings[1]!.generated).toBe(true);
    expect(headings[2]!.generated, "later raw heading keeps its authored id, unrewritten").toBe(false);
  });

  it("pins raw-vs-raw duplicate ids exactly as authored (no behaviour change)", async () => {
    const headings = await headingsOf("raw-vs-raw.md");
    expect(idList(headings)).toEqual(BASELINE_IDS["raw-vs-raw.md"]);
  });

  it("moves only the Markdown heading after a raw duplicate pair (to -1)", async () => {
    const headings = await headingsOf("raw-pair-md.md");
    expect(idList(headings)).toEqual(["h1:report-title", "h2:notes", "h2:notes", "h2:notes-1"]);
  });

  it("renumbers nothing around a collision: neighbours keep today's ids", async () => {
    const headings = await headingsOf("collision-with-dupes.md");
    expect(idList(headings)).toEqual([
      "h1:report-title",
      "h2:setup",
      "h2:summary",
      "h2:summary-1",
      "h2:setup-1",
      "h2:wrap-up",
    ]);
  });

  it("skips over a raw-authored suffixed id instead of duplicating it", async () => {
    const headings = await headingsOf("suffixed-raw.md");
    expect(idList(headings)).toEqual(["h1:report-title", "h2:notes-1", "h2:notes", "h2:notes-2"]);
    expect(duplicates(idList(headings).map((s) => s.slice(3)))).toEqual([]);
  });

  it.each(["repro.md", "raw-first-levels.md", "raw-first-triple.md", "collision-with-dupes.md", "suffixed-raw.md"])(
    "every in-page fragment in %s resolves to exactly one element, first heading keeping its id",
    async (path) => {
      const html = articleHtml(await page(path));
      const { links, ids } = await fragmentsIn(html);
      expect(links.length).toBeGreaterThan(0);
      for (const target of links) {
        expect(ids.filter((id) => id === target), `#${target} matches exactly one element`).toHaveLength(1);
      }
    },
  );

  it.each(Object.keys(BASELINE_IDS))("keeps every heading id of %s byte-identical to render version 3", async (path) => {
    expect(idList(await headingsOf(path))).toEqual(BASELINE_IDS[path]);
  });

  it.each(Object.keys(GOLDEN_B64))("serves %s byte-identical to render version 3 (no collision, no renumbering)", async (path) => {
    const res = await get(path);
    expect(res.status).toBe(200);
    expect(new Uint8Array(await res.arrayBuffer())).toEqual(new TextEncoder().encode(new TextDecoder().decode(decodeB64(GOLDEN_B64[path]!)).split("kofra-golden-slug").join(slug)));
  });

  it("serves a raw heading without an id without inventing one (sanitizer unchanged)", async () => {
    const headings = await headingsOf("raw-no-id.md");
    expect(headings.map((h) => h.id)).toEqual(["report-title", null, "unlabelled-raw"]);
    expect(headings[1]!.generated).toBe(false);
  });

  it("keeps sanitizer id handling for authored ids and never surfaces dropped markup", async () => {
    const html = await page("dropped-ids.md");
    expect(html).not.toMatch(/<script\b/i);
    expect(html).not.toContain("alert(");
    const { ids } = await fragmentsIn(articleHtml(html));
    expect(ids).toEqual(["report-title", "kept", "inline"]);
    const rawUnique = articleHtml(await page("raw-unique.md"));
    expect(rawUnique).toContain('id="raw-custom"');
  });

  it("does not let a non-heading element id steal a heading anchor (out of scope)", async () => {
    const headings = await headingsOf("non-heading-id.md");
    expect(idList(headings)).toEqual(BASELINE_IDS["non-heading-id.md"]);
  });

  it("retires the pre-fix render identity (viewer version bumped with the byte change)", () => {
    expect(markdownViewer.version).toBeGreaterThan(BASELINE_MD_VERSION);
  });

  it.each(["memory", "edge"])("cannot serve a cached pre-fix fragment with duplicate ids from the %s tier", async (tier) => {
    const hash = await sha256Hex(new TextEncoder().encode(fixtures["repro.md"]!));
    const legacyKey = `markdown@${BASELINE_MD_VERSION}/${hash}`;
    const url = `${ORIGIN}/s/${slug}/repro.md`;
    const oldHtml =
      '<!--title:Report Title--><h1 id="report-title">T</h1><h2 id="markdown-section">Raw</h2><h2 id="markdown-section">Md LEGACY_DUPLICATE_IDS</h2>';
    await caches.default.delete(new Request(`${ORIGIN}/__dropway/render/${legacyKey}`));
    await caches.default.delete(new Request(`${ORIGIN}/__dropway/render/markdown@${markdownViewer.version}/${hash}`));
    if (tier === "memory") {
      const ctx = createExecutionContext();
      const dc = dw.dropway.context(env as unknown as ServerBindings, ctx, new URL(url));
      await cachedRender(dc, legacyKey, async () => oldHtml);
      await waitOnExecutionContext(ctx);
    } else {
      await caches.default.put(new Request(`${ORIGIN}/__dropway/render/${legacyKey}`), new Response(oldHtml, {
        headers: { "Content-Type": "text/html", "Cache-Control": "public, max-age=2592000" },
      }));
      clearRenderMemoryCache();
    }
    const res = await dw.call(url, { headers: NAV });
    const html = await res.text();
    expect(html).not.toContain("LEGACY_DUPLICATE_IDS");
    expect(idList(await headingsIn(articleHtml(html)))).toEqual(["h1:report-title", "h2:markdown-section", "h2:markdown-section-1"]);
    expect(res.headers.get("x-kofra-render-cache")).toBe("miss");
    const again = await dw.call(url, { headers: NAV });
    expect(again.headers.get("x-kofra-render-cache")).toBe("memory");
  });

  it("does not answer 304 to a pre-fix ETag, but revalidates the new render", async () => {
    const hash = await sha256Hex(new TextEncoder().encode(fixtures["repro.md"]!));
    const legacy = `W/"markdown@${BASELINE_MD_VERSION}-${hash}"`;
    const res = await get("repro.md", { ...NAV, "If-None-Match": legacy });
    expect(res.status).toBe(200);
    const etag = res.headers.get("etag")!;
    expect(etag).not.toBe(legacy);
    expect(etag).toMatch(/^W\/"markdown@\d+-[a-f0-9]{64}(-[^"]*)?"$/); expect(Number(/markdown@(\d+)/.exec(etag)![1])).toBeGreaterThan(BASELINE_MD_VERSION);
    expect(idList(await headingsIn(articleHtml(await res.text())))).toEqual([
      "h1:report-title",
      "h2:markdown-section",
      "h2:markdown-section-1",
    ]);
    const fresh = await get("repro.md", { ...NAV, "If-None-Match": etag });
    expect(fresh.status).toBe(304);
    expect(await fresh.text()).toBe("");
  });

  it("serves raw and download bytes of a collision document unchanged", async () => {
    for (const query of ["?raw=1", "?download=1"]) {
      const res = await get(`repro.md${query}`);
      expect(res.status).toBe(200);
      expect(res.headers.get("x-kofra-viewer")).toBeNull();
      expect(new Uint8Array(await res.arrayBuffer())).toEqual(new TextEncoder().encode(fixtures["repro.md"]!));
    }
  });
});

describe("renderMarkdown() helper (the fragment the viewer's sanitizer refines)", () => {
  it("assigns the suffix at render time so embedded fragments are unambiguous too", async () => {
    const out = renderMarkdown(fixtures["repro.md"]!, "repro.md");
    const { ids } = await fragmentsIn(out.html);
    expect(duplicates(ids)).toEqual([]);
    expect(ids).toEqual(["report-title", "markdown-section", "markdown-section-1"]);
  });

  it("keeps helper ids byte-identical for a collision-free document", async () => {
    const out = renderMarkdown(fixtures["plain.md"]!, "plain.md");
    const { ids } = await fragmentsIn(out.html);
    expect(ids).toEqual(["first-report", "second-section"]);
  });
});
